//! `ConLeche/Kernel/Basis/{Eq,Nat,PUnit,Empty,False,Quot}.lean` and
//! `ConLeche/Kernel/Basis.lean` — the **raw** pinned basis blocks: each block
//! exactly as an export carries it, the toolchain's `Init.Prelude`
//! declaration at the parser's raw binder annotations — plus the two tests
//! that recognise one in a stream record.
//!
//! **Why they are in the verified core.**  con-ron-core carries the
//! *annotated* blocks (`kernel::basis_tables`, `BasisKind.declsA`,
//! generated by task #22), which is what the installation stores; the raw
//! pins are what an incoming record is MATCHED against.  Until con-leche
//! task #293 that match was the parser's, and this module lived in the
//! unverified crate beside it (`con_ron::frontend::basis_raw`).  Task #293
//! moved the recognition into the fold: the decoder emits the file's records
//! and nothing else, `prepare_prelude` only reorders them, and it is
//! `check_decl` that recognises a block as one of the five pins
//! (`basis_pin_hit` below) and a `#QUOT` record — or the `Quot.sound` axiom
//! record — as the pinned quotient package's (`quot_pin_hit` below).  The
//! match is part of the verdict, so the pins and the two tests are part of
//! the verified core.
//!
//! **Why there are two tables.**  The raw pins could not be borrowed from
//! `basis_tables`: `canonEq` resets binder metadata and `IndCaps` on both
//! sides but compares a recursor rule's install-computed fields
//! (`ctorParams`, `fire`, `k`, `eta`, `paramsBlind`) verbatim, and the
//! annotated `Nat.rec` rule carries `ctorParams = 2`, `fire = .plain`,
//! `k = true`, `paramsBlind = true` where a parsed one carries the
//! placeholders.  A stream's `Nat` block would then never match the pin,
//! which is a verdict divergence, not a cosmetic one.  The module's own
//! tests check that claim both ways.
//!
//! con-leche's own module split is the same one for the same reason:
//! `Kernel/Basis.lean` (the raw pins) sits BELOW `Kernel/TypeChecker`
//! because "the kernel core needs the raw pins … and nothing else", and
//! `Kernel/BasisA.lean` sits above it.
//!
//! Written with con-ron-core's port of the raw-pin DSL
//! (`kernel::basis_builder`, task #18), so a reader can line each pin up
//! against `Init.Prelude` binder by binder exactly as in the Lean.  The
//! DSL's own deviation stands: `pi`/`piI`/`piA` are one function and
//! `lm`/`lmI` are one, because `Expr` carries neither a binder name nor a
//! binder info.

use crate::kernel::basis_builder::{ap2, ap3, bv, cnst, lm, pi, prop, srt, type1, u, u1};
use crate::kernel::basis_builder::{u1_n, u_n, v, v_n};
use crate::kernel::basis_names as bnm;
use crate::kernel::canon;
use crate::kernel::env;
use crate::kernel::env::{BasisKind, ConstantInfo, ConstantVal, IndCaps, QuotKind, RecRule};
use crate::kernel::expr;
use crate::kernel::expr::Expr;
use crate::kernel::name;
use crate::kernel::name::Name;
use crate::kernel::prop_when;

/// con-leche: none — `ConstantVal.mk` at the anonymous-constructor literal
/// `⟨name, lps, ty⟩` every pin below opens with.
pub fn cv(n: Name, lps: Vec<Name>, ty: Expr) -> ConstantVal {
    ConstantVal {
        name: n,
        level_params: lps,
        ty,
    }
}

/// con-leche: ConLeche/Kernel/Basis/Builder.lean:117-121 BasisDSL.rule
/// A raw iota rule: the install-computed fields (`ctorParams`, `fire`, `k`,
/// `eta`, `paramsBlind`) at their parse placeholders, which is what the
/// exporter emits and what `#annotate_basis` recomputes.
pub fn rule(ctor: Name, nfields: u64, rhs: Expr) -> RecRule {
    env::rec_rule_parsed(ctor, nfields, rhs)
}

// --- Eq --------------------------------------------------------------------

/// con-leche: ConLeche/Kernel/Basis/Eq.lean:22-28 eqRaw
/// `Eq.{u} {α : Sort u} : α → α → Prop`.
pub fn eq_raw() -> ConstantInfo {
    let caps = IndCaps {
        rule_k: true,
        ..env::ind_caps_default()
    };
    ConstantInfo::IndInfo(
        cv(
            bnm::eq_name(),
            vec![u_n()],
            pi(srt(u()), pi(bv(0), pi(bv(1), prop()))),
        ),
        caps,
    )
}

/// con-leche: ConLeche/Kernel/Basis/Eq.lean:30-36 eqReflRaw
/// `Eq.refl.{u} {α : Sort u} (a : α) : Eq α a a`.
pub fn eq_refl_raw() -> ConstantInfo {
    ConstantInfo::CtorInfo(
        cv(
            bnm::eq_refl_name(),
            vec![u_n()],
            pi(
                srt(u()),
                pi(
                    bv(0),
                    ap3(cnst(bnm::eq_name(), vec![u()]), bv(1), bv(0), bv(0)),
                ),
            ),
        ),
        2,
        0,
    )
}

/// con-leche: ConLeche/Kernel/Basis/Eq.lean:38-42 eqRecMotive
/// The motive of `Eq.rec`: `∀ (b : α) (t : Eq α a b), Sort u_1`, in the
/// `α`/`a` binder context (`α` is `#1`, `a` is `#0` at its head).
pub fn eq_rec_motive() -> Expr {
    pi(
        bv(1),
        pi(
            ap3(cnst(bnm::eq_name(), vec![u()]), bv(2), bv(1), bv(0)),
            srt(u1()),
        ),
    )
}

/// con-leche: none — `Eq.rec`'s `refl` minor premise, `motive a (Eq.refl α
/// a)`, which `eqRecRaw` spells twice (in its type and in its iota rule).
pub fn eq_rec_refl_dom() -> Expr {
    ap2(
        bv(0),
        bv(1),
        ap2(cnst(bnm::eq_refl_name(), vec![u()]), bv(2), bv(1)),
    )
}

/// con-leche: ConLeche/Kernel/Basis/Eq.lean:44-61 eqRecRaw
/// `Eq.rec.{u_1, u} {α : Sort u} {a : α} {motive : ∀ b, Eq α a b → Sort u_1}
/// (refl : motive a (Eq.refl α a)) {b : α} (t : Eq α a b) : motive b t`.
pub fn eq_rec_raw() -> ConstantInfo {
    ConstantInfo::RecInfo(
        cv(
            bnm::rec_of(bnm::eq_name()),
            vec![u1_n(), u_n()],
            pi(
                srt(u()),
                pi(
                    bv(0),
                    pi(
                        eq_rec_motive(),
                        pi(
                            eq_rec_refl_dom(),
                            pi(
                                bv(3),
                                pi(
                                    ap3(cnst(bnm::eq_name(), vec![u()]), bv(4), bv(3), bv(0)),
                                    ap2(bv(3), bv(1), bv(0)),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        ),
        5,
        4,
        vec![rule(
            bnm::eq_refl_name(),
            0,
            lm(
                srt(u()),
                lm(
                    bv(0),
                    lm(eq_rec_motive(), lm(eq_rec_refl_dom(), bv(0))),
                ),
            ),
        )],
    )
}

/// con-leche: ConLeche/Kernel/Basis/Eq.lean:63-64 eqBasis
/// The pinned `Eq` basis block, in install order.
pub fn eq_basis() -> Vec<ConstantInfo> {
    vec![eq_raw(), eq_refl_raw(), eq_rec_raw()]
}

