/// con-leche: ConLeche/Kernel/Basis/PUnit.lean:24-29 punitRaw
/// `PUnit.{u} : Sort u`.
pub fn punit_raw() -> ConstantInfo {
    let caps = IndCaps {
        eta: true,
        eta_ctor: bnm::punit_unit_name(),
        eta_params: 0,
        eta_fields: 0,
        unitlike: true,
        sort_z: prop_when::if_all_zero(vec![u_n()]),
        ..env::ind_caps_default()
    };
    ConstantInfo::IndInfo(cv(bnm::punit_name(), vec![u_n()], srt(u())), caps)
}

